/**
 * Theme system for CampusNav.
 * Exports color palettes, spacing scale, typography, and the useTheme hook.
 */

import { useColorScheme } from 'react-native';

import { darkColors, lightColors } from './colors';
import { spacing } from './spacing';
import { typography } from './typography';

export { darkColors, lightColors } from './colors';
export { spacing } from './spacing';
export { typography } from './typography';

export interface Theme {
  colors: typeof darkColors | typeof lightColors;
  spacing: typeof spacing;
  typography: typeof typography;
  isDark: boolean;
}

/**
 * Returns the current theme based on the system color scheme.
 *
 * Usage:
 *   const { colors, spacing, typography, isDark } = useTheme();
 */
export function useTheme(): Theme {
  const colorScheme = useColorScheme();
  const isDark = colorScheme === 'dark';
  return {
    colors: isDark ? darkColors : lightColors,
    spacing,
    typography,
    isDark,
  };
}

/**
 * Spacing scale based on a 4pt grid.
 * All spacing values are multiples of 4 for visual consistency.
 */

export const spacing = {
  /** 4px */
  xs: 4,
  /** 8px */
  sm: 8,
  /** 12px */
  md: 12,
  /** 16px */
  lg: 16,
  /** 24px */
  xl: 24,
  /** 32px */
  '2xl': 32,
  /** 48px */
  '3xl': 48,
  /** 64px */
  '4xl': 64,
} as const;

// oxc workaround: removed export type; keeping const-only export
// Spacing is only used as a TypeScript type (stripped at runtime)
export const Spacing = undefined as unknown as Record<string, number>;

/**
 * Typography tokens for CampusNav.
 * Text styles derived from existing component usage.
 */

import { TextStyle } from 'react-native';

export const typography = {
  title: {
    fontSize: 20,
    fontWeight: '700',
    lineHeight: 28,
  } satisfies TextStyle,

  sectionHeader: {
    fontSize: 16,
    fontWeight: '600',
    lineHeight: 22,
  } satisfies TextStyle,

  body: {
    fontSize: 15,
    fontWeight: '400',
    lineHeight: 22,
  } satisfies TextStyle,

  bodyBold: {
    fontSize: 15,
    fontWeight: '600',
    lineHeight: 22,
  } satisfies TextStyle,

  caption: {
    fontSize: 12,
    fontWeight: '400',
    lineHeight: 16,
  } satisfies TextStyle,

  captionBold: {
    fontSize: 12,
    fontWeight: '600',
    lineHeight: 16,
  } satisfies TextStyle,

  label: {
    fontSize: 11,
    fontWeight: '600',
    letterSpacing: 1,
    textTransform: 'uppercase',
  } satisfies TextStyle,

  chip: {
    fontSize: 12,
    fontWeight: '500',
  } satisfies TextStyle,
} as const;

// oxc workaround: removed export type; keeping const-only export
// Typography is only used as a TypeScript type (stripped at runtime)
export const Typography = undefined as unknown as Record<string, TextStyle>;

import { NavBuilding, NavEdge, NavFloor, NavGraph, NavNode } from '../../src/shared/types';
import {
  type NavGraphContractValidationError,
  validateNavGraphPayload,
} from './navGraphSchema';
import { PathResult, PathSegment, RouteMode } from '../../src/shared/pathfinding/types';

// Re-export pathfinding types so routing module can import everything from domain/navGraph
export { PathResult, PathSegment, RouteMode };

/**
 * Direction generation types — turn-by-turn step generation.
 *
 * Used by mobile/routing/generateDirections.ts to convert computed paths
 * into human-readable walking instructions.
 */

/**
 * Icon types for direction step visualization.
 * Maps to icons in the mobile UI icon set.
 */
export type StepIcon =
  | 'straight'
  | 'turn-left'
  | 'turn-right'
  | 'sharp-left'
  | 'sharp-right'
  | 'arrive'
  | 'accessible'
  | 'stairs-up'
  | 'stairs-down'
  | 'elevator'
  | 'ramp';
export const StepIcon = undefined as unknown as StepIcon;

/**
 * A single turn-by-turn direction instruction.
 */
export interface DirectionStep {
  /** Human-readable instruction, e.g. "Turn left at the cafeteria" */
  instruction: string;
  icon: StepIcon;
  /** Segment distance in normalized units (0–1 coordinate space) */
  distanceM: number;
  /** Estimated seconds for this segment */
  durationSec: number;
  /** True if this segment passes through a ramp or elevator node */
  isAccessibleSegment: boolean;
  /** Floor ID where this instruction is presented */
  floorId: number;
  /** Resolved floor number for display/grouping; falls back to floorId when metadata is missing */
  floorNumber: number;
}

/**
 * Complete result of direction generation.
 */
export interface DirectionsResult {
  steps: DirectionStep[];
  /** Sum of all segment distances in normalized units */
  totalDistanceNorm: number;
  /** Sum of all step durations in seconds */
  totalDurationSec: number;
}

/**
 * A section of directions on a single floor.
 * Used by mobile/routing/directionSections.ts for floor-grouped display.
 */
export interface DirectionSection {
  floorId: number;
  floorNumber: number;
  steps: DirectionStep[];
}

export interface NormalizedFloorRecord {
  buildingId: number;
  buildingName: string;
  floor: NavFloor;
}

export interface NormalizedNodeRecord {
  buildingId: number;
  buildingName: string;
  floorId: number;
  floorNumber: number;
  node: NavNode;
}

export interface NormalizedEdgeRecord {
  buildingId: number;
  floorId: number;
  edge: NavEdge;
  effectiveAccessibleWeight: number;
}

export interface NormalizedNavGraph {
  graph: NavGraph;
  buildingById: Map<number, NavBuilding>;
  floorById: Map<number, NormalizedFloorRecord>;
  floorByBuildingAndNumber: Map<string, NormalizedFloorRecord>;
  nodeById: Map<string, NormalizedNodeRecord>;
  edgeById: Map<string, NormalizedEdgeRecord>;
  outgoingEdgesByNodeId: Map<string, NormalizedEdgeRecord[]>;
}

export type NavGraphNormalizationErrorCode =
  | 'duplicate-building-id'
  | 'duplicate-floor-id'
  | 'duplicate-floor-number-per-building'
  | 'duplicate-node-id'
  | 'duplicate-edge-id'
  | 'node-floor-mismatch'
  | 'edge-node-missing';
export const NavGraphNormalizationErrorCode = undefined as unknown as NavGraphNormalizationErrorCode;

export interface NavGraphNormalizationError {
  reason: 'normalization-failure';
  code: NavGraphNormalizationErrorCode;
  message: string;
}

export type NavGraphNormalizationResult =
  | { ok: true; data: NormalizedNavGraph }
  | { ok: false; error: NavGraphNormalizationError };
export const NavGraphNormalizationResult = undefined as unknown as NavGraphNormalizationResult;

export type NavGraphParseAndNormalizeResult =
  | { ok: true; data: NormalizedNavGraph }
  | { ok: false; error: NavGraphContractValidationError | NavGraphNormalizationError };
export const NavGraphParseAndNormalizeResult = undefined as unknown as NavGraphParseAndNormalizeResult;

function fail(
  code: NavGraphNormalizationErrorCode,
  message: string,
): { ok: false; error: NavGraphNormalizationError } {
  return {
    ok: false,
    error: {
      reason: 'normalization-failure',
      code,
      message,
    },
  };
}

export function floorLookupKey(buildingId: number, floorNumber: number): string {
  return `${buildingId}:${floorNumber}`;
}

export function getEffectiveAccessibleWeight(edge: Pick<NavEdge, 'accessible' | 'accessibleWeight'>): number {
  return edge.accessible ? edge.accessibleWeight : Number.POSITIVE_INFINITY;
}

/**
 * Calculate the bearing (angle) from point A to point B in screen-space coordinates.
 * 0° = north (positive y), 90° = east (positive x), 180° = south, 270° = west.
 * Returns value normalized to [0, 360).
 */
export function bearing(ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax;
  const dy = by - ay;

  // Handle same-point case (division by zero)
  if (dx === 0 && dy === 0) {
    return 0;
  }

  // In screen-space: north = positive y, east = positive x.
  // atan2(y, x) gives angle from east axis (standard math convention).
  // Since east is +90° from north in our system, we rotate by +270° (same as -90°).
  // Use -dx instead of dx because screen x-axis points opposite to math x-axis.
  // Formula: atan2(dy, -dx) * (180/π) + 270, normalized to [0, 360).
  let angle = Math.atan2(dy, -dx) * (180 / Math.PI) + 270;

  // Normalize to [0, 360)
  if (angle < 0) {
    angle += 360;
  }
  angle = angle % 360;

  return angle;
}

/**
 * Normalize an angular delta to the range [-180, 180].
 * Used for calculating the shortest turn direction.
 */
export function normalizeDelta(delta: number): number {
  let result = delta % 360;
  if (result > 180) {
    result -= 360;
  } else if (result < -180) {
    result += 360;
  }
  return result;
}

export function normalizeNavGraph(graph: NavGraph): NavGraphNormalizationResult {
  const buildingById = new Map<number, NavBuilding>();
  const floorById = new Map<number, NormalizedFloorRecord>();
  const floorByBuildingAndNumber = new Map<string, NormalizedFloorRecord>();
  const nodeById = new Map<string, NormalizedNodeRecord>();
  const edgeById = new Map<string, NormalizedEdgeRecord>();
  const outgoingEdgesByNodeId = new Map<string, NormalizedEdgeRecord[]>();

  for (const building of graph.buildings) {
    if (buildingById.has(building.id)) {
      return fail('duplicate-building-id', `Duplicate building id detected: ${building.id}.`);
    }

    buildingById.set(building.id, building);

    for (const floor of building.floors) {
      if (floorById.has(floor.id)) {
        return fail('duplicate-floor-id', `Duplicate floor id detected: ${floor.id}.`);
      }

      const floorKey = floorLookupKey(building.id, floor.floorNumber);
      if (floorByBuildingAndNumber.has(floorKey)) {
        return fail(
          'duplicate-floor-number-per-building',
          `Duplicate floor number ${floor.floorNumber} for building ${building.id}.`,
        );
      }

      const floorRecord: NormalizedFloorRecord = {
        buildingId: building.id,
        buildingName: building.name,
        floor,
      };

      floorById.set(floor.id, floorRecord);
      floorByBuildingAndNumber.set(floorKey, floorRecord);

      for (const node of floor.nodes) {
        if (node.floorId !== floor.id) {
          return fail(
            'node-floor-mismatch',
            `Node ${node.id} reports floorId=${node.floorId}, expected ${floor.id}.`,
          );
        }

        if (nodeById.has(node.id)) {
          return fail('duplicate-node-id', `Duplicate node id detected: ${node.id}.`);
        }

        nodeById.set(node.id, {
          buildingId: building.id,
          buildingName: building.name,
          floorId: floor.id,
          floorNumber: floor.floorNumber,
          node,
        });
      }

      for (const edge of floor.edges) {
        if (edgeById.has(edge.id)) {
          return fail('duplicate-edge-id', `Duplicate edge id detected: ${edge.id}.`);
        }

        const edgeRecord: NormalizedEdgeRecord = {
          buildingId: building.id,
          floorId: floor.id,
          edge,
          effectiveAccessibleWeight: getEffectiveAccessibleWeight(edge),
        };

        edgeById.set(edge.id, edgeRecord);
      }
    }
  }

  for (const edgeRecord of edgeById.values()) {
    const source = nodeById.get(edgeRecord.edge.sourceId);
    const target = nodeById.get(edgeRecord.edge.targetId);

    if (!source || !target) {
      return fail(
        'edge-node-missing',
        `Edge ${edgeRecord.edge.id} references missing node(s): ${edgeRecord.edge.sourceId} -> ${edgeRecord.edge.targetId}.`,
      );
    }

    const currentOutgoing = outgoingEdgesByNodeId.get(source.node.id) ?? [];
    currentOutgoing.push(edgeRecord);
    outgoingEdgesByNodeId.set(source.node.id, currentOutgoing);
  }

  return {
    ok: true,
    data: {
      graph,
      buildingById,
      floorById,
      floorByBuildingAndNumber,
      nodeById,
      edgeById,
      outgoingEdgesByNodeId,
    },
  };
}

export function parseAndNormalizeNavGraph(payload: unknown): NavGraphParseAndNormalizeResult {
  const validated = validateNavGraphPayload(payload);
  if (!validated.ok) {
    return validated;
  }

  return normalizeNavGraph(validated.data);
}

import { NavGraph } from '../../src/shared/types';
import { validateNavGraphPayload } from '../domain/navGraphSchema';

// oxc workaround: export type declarations removed to avoid TypeScript export type parsing failure
// Types are used at compile time only (stripped by TypeScript); runtime value is undefined
export const MapApiErrorReason = undefined as unknown as MapApiErrorReason;

export interface MapApiError {
  endpoint: string;
  status: number | null;
  reason: MapApiErrorReason;
  attempt: number;
  message: string;
  details?: string[];
}

// oxc workaround: MapApiResult must be exported as both type and runtime value
export type MapApiResult<T> = {
  ok: true;
  endpoint: string;
  status: number;
  attempt: number;
  data: T;
} | {
  ok: false;
  error: MapApiError;
};
export const MapApiResult = undefined as unknown as MapApiResult<unknown>;

export interface MapImageContract {
  endpoint: string;
  contentType: string;
  cacheControl: string | null;
}

export interface FloorPlanTarget {
  buildingId: number;
  floorNumber: number;
}

export interface MapApiRetryPolicy {
  maxAttempts: number;
  baseDelayMs: number;
  timeoutMs: number;
}

export const Fetcher = undefined as unknown as Fetcher;

export interface MapApiClientConfig {
  baseUrl: string;
  fetchImpl?: Fetcher;
  retryPolicy?: Partial<MapApiRetryPolicy>;
  sleep?: (ms: number) => Promise<void>;
}

export interface MapApiRequestOptions {
  signal?: AbortSignal;
  maxAttempts?: number;
  timeoutMs?: number;
}

interface AttemptSignal {
  signal: AbortSignal;
  cleanup: () => void;
  didTimeout: () => boolean;
}

interface HttpSuccess {
  ok: true;
  endpoint: string;
  attempt: number;
  response: Response;
}

interface HttpFailure {
  ok: false;
  error: MapApiError;
}

type HttpMapResult = HttpSuccess | HttpFailure;
type HttpImageResult = HttpSuccess | HttpFailure;

export const MapGraphResult = undefined as unknown as MapGraphResult;
export const FloorPlanImageResult = undefined as unknown as FloorPlanImageResult;

const DEFAULT_RETRY_POLICY: MapApiRetryPolicy = {
  maxAttempts: 3,
  baseDelayMs: 200,
  timeoutMs: 2_000,
};

function withHardTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
): Promise<T> {
  let timeoutHandle: ReturnType<typeof setTimeout>;
  return Promise.race([
    promise,
    new Promise<never>((_, reject) => {
      timeoutHandle = setTimeout(() => {
        reject(new Error('timeout'));
      }, timeoutMs);
    }),
  ]).finally(() => {
    clearTimeout(timeoutHandle!);
  });
}

function normalizeBaseUrl(baseUrl: string): string {
  const parsed = new URL(baseUrl);
  parsed.hash = '';
  parsed.search = '';
  return parsed.toString().replace(/\/$/, '');
}

function resolveEndpoint(baseUrl: string, pathname: string): string {
  return new URL(pathname, `${baseUrl}/`).toString();
}

function createApiError(
  endpoint: string,
  attempt: number,
  reason: MapApiErrorReason,
  message: string,
  status: number | null = null,
  details?: string[],
): MapApiError {
  return {
    endpoint,
    status,
    reason,
    attempt,
    message,
    ...(details && details.length > 0 ? { details } : {}),
  };
}

function isRetryableHttpStatus(status: number): boolean {
  return status === 429 || status >= 500;
}

function isAbortError(error: unknown): boolean {
  // DOMException is not available in React Native Hermes
  if (typeof DOMException !== 'undefined' && error instanceof DOMException) {
    return error.name === 'AbortError';
  }
  return error instanceof Error && error.name === 'AbortError';
}

/** React Native-safe abort error (no DOMException in Hermes) */
function makeAbortError(): Error {
  const err = new Error('Aborted');
  err.name = 'AbortError';
  return err;
}

function createAttemptSignal(externalSignal: AbortSignal | undefined, timeoutMs: number) {
  const controller = new AbortController();
  let timeoutTriggered = false;

  const onExternalAbort = () => {
    controller.abort(externalSignal?.reason);
  };

  if (externalSignal) {
    if (externalSignal.aborted) {
      controller.abort(externalSignal.reason);
    } else {
      externalSignal.addEventListener('abort', onExternalAbort, { once: true });
    }
  }

  const timeoutHandle = setTimeout(() => {
    timeoutTriggered = true;
    controller.abort(new Error('timeout'));
  }, timeoutMs);

  const cleanup = () => {
    clearTimeout(timeoutHandle);
    if (externalSignal && !externalSignal.aborted) {
      externalSignal.removeEventListener('abort', onExternalAbort);
    }
  };

  return {
    signal: controller.signal,
    cleanup,
    didTimeout: () => timeoutTriggered,
  };
}

function createSleepWithSignal(
  sleepImpl: (ms: number) => Promise<void>,
  signal: AbortSignal | undefined,
) {
  return async (ms: number) => {
    if (ms <= 0) {
      return;
    }

    if (!signal) {
      await sleepImpl(ms);
      return;
    }

    if (signal.aborted) {
      throw makeAbortError();
    }

    await new Promise<void>((resolve, reject) => {
      const timeoutHandle = setTimeout(() => {
        signal.removeEventListener('abort', onAbort);
        resolve();
      }, ms);

      const onAbort = () => {
        clearTimeout(timeoutHandle);
        reject(makeAbortError());
      };

      signal.addEventListener('abort', onAbort, { once: true });
    });
  };
}

export interface MapApiClient {
  fetchMapGraph(options?: MapApiRequestOptions): Promise<MapGraphResult>;
  fetchFloorPlanImageContract(
    target: FloorPlanTarget,
    options?: MapApiRequestOptions,
  ): Promise<FloorPlanImageResult>;
  fetchCampusImageContract(options?: MapApiRequestOptions): Promise<FloorPlanImageResult>;
  resolveMapUrl(): string;
  resolveFloorPlanImageUrl(target: FloorPlanTarget): string;
  resolveCampusImageUrl(): string;
}

export function createMapApiClient(config: MapApiClientConfig): MapApiClient {
  const baseUrl = normalizeBaseUrl(config.baseUrl);
  const fetchImpl: Fetcher =
    config.fetchImpl ?? ((input, init) => fetch(input, init));
  const retryPolicy: MapApiRetryPolicy = {
    ...DEFAULT_RETRY_POLICY,
    ...config.retryPolicy,
  };
  const sleepImpl = config.sleep ?? ((ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms)));

  async function executeGet(
    endpoint: string,
    options: MapApiRequestOptions | undefined,
  ): Promise<HttpMapResult> {
    const maxAttempts = options?.maxAttempts ?? retryPolicy.maxAttempts;
    const timeoutMs = options?.timeoutMs ?? retryPolicy.timeoutMs;
    const sleepWithSignal = createSleepWithSignal(sleepImpl, options?.signal);

    let lastError: MapApiError | null = null;

    for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
      try {
        const response = await withHardTimeout(
          fetchImpl(endpoint, { method: 'GET' }),
          timeoutMs,
        );

        if (!response.ok) {
          const error = createApiError(
            endpoint,
            attempt,
            'http-error',
            `Request failed with HTTP ${response.status}.`,
            response.status,
          );

          if (attempt < maxAttempts && isRetryableHttpStatus(response.status)) {
            lastError = error;
            const delay = retryPolicy.baseDelayMs * 2 ** (attempt - 1);
            try {
              await sleepWithSignal(delay);
            } catch {
              break;
            }
            continue;
          }

          return { ok: false, error };
        }

        return {
          ok: true,
          endpoint,
          attempt,
          response,
        };
      } catch (error) {
        const isTimeout = error instanceof Error && error.message === 'timeout';
        const reason: MapApiErrorReason = isTimeout
          ? 'timeout'
          : (options?.signal?.aborted || isAbortError(error))
            ? 'aborted'
            : 'network-error';

        const apiError = createApiError(
          endpoint,
          attempt,
          reason,
          reason === 'timeout'
            ? `Request timed out after ${timeoutMs}ms.`
            : reason === 'aborted'
              ? 'Request was aborted.'
              : error instanceof Error
                ? error.message
                : 'Network request failed.',
        );

        const shouldRetry = reason !== 'aborted' && attempt < maxAttempts;
        if (shouldRetry) {
          lastError = apiError;
          const delay = retryPolicy.baseDelayMs * 2 ** (attempt - 1);
          try {
            await sleepWithSignal(delay);
          } catch {
            break;
          }
          continue;
        }

        return { ok: false, error: apiError };
      }
    }

    return {
      ok: false,
      error:
        lastError ??
        createApiError(endpoint, maxAttempts, 'network-error', 'Request failed after retries.'),
    };
  }

  async function fetchMapGraph(options?: MapApiRequestOptions): Promise<MapGraphResult> {
    const endpoint = resolveMapEndpoint(baseUrl);
    const responseResult = await executeGet(endpoint, options);

    if (!responseResult.ok) {
      return responseResult;
    }

    let payload: unknown;

    try {
      payload = await responseResult.response.json();
    } catch (error) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'invalid-json',
          error instanceof Error ? error.message : 'Response body is not valid JSON.',
          responseResult.response.status,
        ),
      };
    }

    const validated = validateNavGraphPayload(payload);
    if (!validated.ok) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'contract-validation-error',
          validated.error.message,
          responseResult.response.status,
          validated.error.issues,
        ),
      };
    }

    return {
      ok: true,
      endpoint,
      status: responseResult.response.status,
      attempt: responseResult.attempt,
      data: validated.data,
    };
  }

  async function fetchImageContract(
    endpoint: string,
    options?: MapApiRequestOptions,
  ): Promise<FloorPlanImageResult> {
    const responseResult = await executeGet(endpoint, options);

    if (!responseResult.ok) {
      return responseResult;
    }

    const contentType = responseResult.response.headers.get('content-type');
    if (!contentType || !contentType.toLowerCase().startsWith('image/')) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'unexpected-content-type',
          `Expected image content-type but received "${contentType ?? 'missing'}".`,
          responseResult.response.status,
        ),
      };
    }

    return {
      ok: true,
      endpoint,
      status: responseResult.response.status,
      attempt: responseResult.attempt,
      data: {
        endpoint,
        contentType,
        cacheControl: responseResult.response.headers.get('cache-control'),
      },
    };
  }

  function resolveMapUrl(): string {
    return resolveMapEndpoint(baseUrl);
  }

  function resolveFloorPlanImageUrl(target: FloorPlanTarget): string {
    return resolveFloorPlanImageEndpoint(baseUrl, target);
  }

  function resolveCampusImageUrl(): string {
    return resolveCampusImageEndpoint(baseUrl);
  }

  async function fetchFloorPlanImageContract(
    target: FloorPlanTarget,
    options?: MapApiRequestOptions,
  ): Promise<FloorPlanImageResult> {
    return fetchImageContract(resolveFloorPlanImageUrl(target), options);
  }

  async function fetchCampusImageContract(options?: MapApiRequestOptions): Promise<FloorPlanImageResult> {
    return fetchImageContract(resolveCampusImageUrl(), options);
  }

  return {
    fetchMapGraph,
    fetchFloorPlanImageContract,
    fetchCampusImageContract,
    resolveMapUrl,
    resolveFloorPlanImageUrl,
    resolveCampusImageUrl,
  };
}

export function resolveMapEndpoint(baseUrl: string): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  return resolveEndpoint(normalizedBaseUrl, '/api/map');
}

export function resolveFloorPlanImageEndpoint(baseUrl: string, target: FloorPlanTarget): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  const buildingId = Number(target.buildingId);
  const floorNumber = Number(target.floorNumber);
  return resolveEndpoint(normalizedBaseUrl, `/api/floor-plan/${buildingId}/${floorNumber}`);
}

export function resolveCampusImageEndpoint(baseUrl: string): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  return resolveEndpoint(normalizedBaseUrl, '/api/campus/image');
}

/**
 * BottomSheet — gesture-driven bottom sheet with 3 snap points.
 *
 * Snap points (distance from bottom of screen):
 *   0 = collapsed  — 120px tall strip
 *   1 = half       — 300px tall
 *   2 = full        — 600px tall
 *
 * The sheet fills the full width and is positioned absolutely
 * at the bottom of its parent.  The three snap heights are
 * relative to the bottom of the screen (collapsed sits 120px
 * above the bottom; half sits 300px above; full reaches 600px
 * below the top of the screen).
 *
 * Usage:
 *   <BottomSheet
 *     snapPoints={[120, 300, 600]}
 *     initialSnapIndex={0}
 *     onSnapChange={(idx) => ...}
 *   >
 *     {content}
 *   </BottomSheet>
 */

import { useCallback } from 'react';
import { Dimensions, LayoutChangeEvent, StyleSheet, View } from 'react-native';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';
import Animated, {
  runOnJS,
  useAnimatedStyle,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';

import { useTheme } from '../../theme';

const { height: SCREEN_HEIGHT } = Dimensions.get('window');

export type SnapIndex = 0 | 1 | 2;

interface Props {
  /** Three snap point heights in pixels. */
  snapPoints?: [number, number, number];
  /** Index into snapPoints for initial position (default 0 = collapsed). */
  initialSnapIndex?: SnapIndex;
  /** Called whenever the sheet settles at a new snap point. */
  onSnapChange?: (index: SnapIndex) => void;
  /** Optional extra styles applied to the sheet container. */
  containerStyle?: object;
  children?: React.ReactNode;
}

/** Snap point heights used throughout S02 layout. */
export const DEFAULT_SNAP_POINTS: [number, number, number] = [120, 300, 600];

/**
 * Returns the Y offset (from screen bottom) for a given snap index.
 * At index 0 (collapsed) the sheet sits 120px above the bottom.
 * At index 2 (full) the sheet's top is 600px below the top.
 * The sheet height is always SCREEN_HEIGHT.
 */
function snapToOffset(index: SnapIndex, snapPoints: [number, number, number]): number {
  // sheetY is the top of the sheet measured from the TOP of the screen.
  // The sheet is always SCREEN_HEIGHT tall.
  // At index 0: sheet top is at SCREEN_HEIGHT - 120 (120px above bottom)
  // At index 1: sheet top is at SCREEN_HEIGHT - 300
  // At index 2: sheet top is at SCREEN_HEIGHT - 600
  return SCREEN_HEIGHT - snapPoints[index];
}

export function BottomSheet({
  snapPoints = DEFAULT_SNAP_POINTS,
  initialSnapIndex = 0,
  onSnapChange,
  containerStyle,
  children,
}: Props) {
  const { colors } = useTheme();

  // Track the sheet's top Y position (measured from screen top).
  const sheetY = useSharedValue(snapToOffset(initialSnapIndex, snapPoints));
  const startY = useSharedValue(sheetY.value);
  const currentSnap = useSharedValue<SnapIndex>(initialSnapIndex);

  const notifySnapChange = useCallback(
    (idx: SnapIndex) => {
      onSnapChange?.(idx);
    },
    [onSnapChange],
  );

  const findNearestSnap = useCallback(
    (currentY: number): SnapIndex => {
      // Find the snap point whose Y position is closest to currentY
      let nearest = 0;
      let minDist = Math.abs(snapToOffset(0, snapPoints) - currentY);
      for (let i = 1; i < snapPoints.length; i++) {
        const dist = Math.abs(snapToOffset(i as SnapIndex, snapPoints) - currentY);
        if (dist < minDist) {
          minDist = dist;
          nearest = i;
        }
      }
      return nearest as SnapIndex;
    },
    [snapPoints],
  );

  const panGesture = Gesture.Pan()
    .onStart(() => {
      startY.value = sheetY.value;
    })
    .onUpdate((event) => {
      const newY = startY.value + event.translationY;
      // Clamp so the sheet never goes fully off-screen at the top
      const minY = SCREEN_HEIGHT - snapPoints[2]; // full = top-most
      const maxY = SCREEN_HEIGHT - snapPoints[0]; // collapsed = bottom-most
      sheetY.value = Math.max(minY, Math.min(maxY, newY));
    })
    .onEnd(() => {
      const nearest = findNearestSnap(sheetY.value);
      sheetY.value = withSpring(snapToOffset(nearest, snapPoints), {
        damping: 50,
        stiffness: 300,
      });
      if (nearest !== currentSnap.value) {
        currentSnap.value = nearest;
        runOnJS(notifySnapChange)(nearest);
      }
    });

  const animatedStyle = useAnimatedStyle(() => ({
    top: sheetY.value,
  }));

  return (
    <GestureDetector gesture={panGesture}>
      <Animated.View
        style={[
          styles.sheet,
          { backgroundColor: colors.surface },
          containerStyle,
          animatedStyle,
        ]}
        accessibilityLabel="Bottom sheet"
      >
        <View style={styles.inner}>{children}</View>
      </Animated.View>
    </GestureDetector>
  );
}

const styles = StyleSheet.create({
  sheet: {
    position: 'absolute',
    left: 0,
    right: 0,
    height: SCREEN_HEIGHT,
    borderTopLeftRadius: 20,
    borderTopRightRadius: 20,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: -4 },
    shadowOpacity: 0.15,
    shadowRadius: 12,
    elevation: 10,
    zIndex: 100,
  },
  inner: {
    flex: 1,
  },
});

/**
 * AccessibleToggle — iOS-style animated switch.
 *
 * Uses react-native-reanimated spring animation to drive the knob
 * between off (left) and on (right) positions.
 * Full ARIA roles and state announcements for screen readers.
 *
 * Usage:
 *   <AccessibleToggle
 *     value={settings.accessibleMode}
 *     onValueChange={(v) => setSettings(s => ({ ...s, accessibleMode: v }))}
 *     disabled={false}
 *     accessibilityLabel="Accessible mode"
 *   />
 */

import { Pressable, StyleSheet, View } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';

import { useTheme } from '../../theme';

interface Props {
  /** Current on/off state. */
  value: boolean;
  /** Called when the user toggles the switch. */
  onValueChange: (value: boolean) => void;
  /** Prevent interaction when true. */
  disabled?: boolean;
  /** Screen-reader label for the track. */
  accessibilityLabel?: string;
  /** Screen-reader hint shown when the control is focused. */
  accessibilityHint?: string;
}

// Spring config for a snappy iOS-like feel
const SPRING_CONFIG = {
  damping: 20,
  stiffness: 400,
  mass: 0.6,
};

const TRACK_WIDTH = 51;   // iOS standard
const TRACK_HEIGHT = 31;  // iOS standard
const KNOB_SIZE = 27;     // iOS standard
const KNOB_MARGIN = 2;    // gap between knob and track edge
const KNOB_TRAVEL = TRACK_WIDTH - KNOB_SIZE - KNOB_MARGIN * 2;

export function AccessibleToggle({
  value,
  onValueChange,
  disabled = false,
  accessibilityLabel = 'Toggle switch',
  accessibilityHint = 'Double tap to change setting',
}: Props) {
  const { colors } = useTheme();
  const knobX = useSharedValue(value ? KNOB_TRAVEL : 0);

  const handleToggle = () => {
    const next = !value;
    knobX.value = withSpring(next ? KNOB_TRAVEL : 0, SPRING_CONFIG);
    onValueChange(next);
  };

  const knobStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: knobX.value }],
  }));

  const trackBg = value ? colors.accent : colors.borderMuted;

  return (
    <Pressable
      onPress={disabled ? undefined : handleToggle}
      disabled={disabled}
      accessibilityRole="switch"
      accessibilityState={{ checked: value, disabled }}
      accessibilityLabel={accessibilityLabel}
      accessibilityHint={accessibilityHint}
      style={styles.container}
    >
      <View
        style={[
          styles.track,
          { backgroundColor: trackBg, opacity: disabled ? 0.4 : 1 },
        ]}
      >
        <Animated.View style={[styles.knob, knobStyle]}>
          {/* Knob highlight — subtle inner shine */}
          <View style={styles.knobHighlight} />
        </Animated.View>
      </View>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  container: {
    alignSelf: 'flex-start',
  },
  track: {
    width: TRACK_WIDTH,
    height: TRACK_HEIGHT,
    borderRadius: TRACK_HEIGHT / 2,
    justifyContent: 'center',
    paddingHorizontal: KNOB_MARGIN,
  },
  knob: {
    width: KNOB_SIZE,
    height: KNOB_SIZE,
    borderRadius: KNOB_SIZE / 2,
    backgroundColor: '#ffffff',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.2,
    shadowRadius: 3,
    elevation: 4,
    overflow: 'hidden',
  },
  knobHighlight: {
