/**
 * FloatingSearchBar — pill-shaped dual-input search widget.
 *
 * Renders a rounded pill containing:
 *   - Origin TextInput (with a location pin icon)
 *   - Swap button (exchanges origin and destination)
 *   - Destination TextInput (with a target icon)
 *
 * All styling driven by useTheme(). Fully accessible with
 * proper labels, roles, and keyboard navigation.
 *
 * Usage:
 *   <FloatingSearchBar
 *     origin={origin}
 *     destination={destination}
 *     onOriginChange={(text) => ...}
 *     onDestinationChange={(text) => ...}
 *     onSwap={() => setOrigin(destination); setDestination(origin)}
 *     onSearchPress={() => ...}
 *   />
 */

import { useCallback } from 'react';
import {
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';
import { useTheme } from '../../theme';

export interface SearchBarInputs {
  origin: string;
  destination: string;
}

export interface FloatingSearchBarProps {
  /** Current origin text. */
  origin: string;
  /** Current destination text. */
  destination: string;
  /** Called when the origin text changes. */
  onOriginChange: (text: string) => void;
  /** Called when the destination text changes. */
  onDestinationChange: (text: string) => void;
  /** Called when the user presses the swap button. */
  onSwap: () => void;
  /** Called when the search/directions button is pressed. */
  onSearchPress: () => void;
  /** Prevent all interactions when true. */
  disabled?: boolean;
  /** Optional extra styles applied to the pill container. */
  style?: object;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/** Returns a shorter secondary label for a location field. */
function fieldLabel(placeholder: string): string {
  if (placeholder.toLowerCase().includes('origin')) return 'From';
  if (placeholder.toLowerCase().includes('destination')) return 'To';
  return placeholder;
}

// ─── Component ────────────────────────────────────────────────────────────────

export function FloatingSearchBar({
  origin,
  destination,
  onOriginChange,
  onDestinationChange,
  onSwap,
  onSearchPress,
  disabled = false,
  style,
}: FloatingSearchBarProps) {
  const { colors, spacing, typography } = useTheme();

  const handleSwap = useCallback(() => {
    if (disabled) return;
    onSwap();
  }, [disabled, onSwap]);

  const handleSearch = useCallback(() => {
    if (disabled) return;
    onSearchPress();
  }, [disabled, onSearchPress]);

  const inputStyle = {
    flex: 1,
    height: 40,
    borderRadius: 20,
    paddingHorizontal: spacing.md,
    fontSize: typography.body.fontSize,
    color: colors.textPrimary,
    backgroundColor: colors.surfaceElevated,
  };

  const activeInputStyle = {
    ...inputStyle,
    borderWidth: 1.5,
    borderColor: colors.borderAccent,
  };

  return (
    <View
      style={[
        styles.pill,
        { backgroundColor: colors.surface },
        disabled && styles.pillDisabled,
        style,
      ]}
      accessibilityRole="none"
    >
      {/* Origin field */}
      <View style={styles.fieldWrapper}>
        <Text
          style={[
            styles.fieldIcon,
            { color: colors.textMuted, fontSize: 14 },
          ]}
          accessibilityElementsHidden
        >
          ◎
        </Text>
        <TextInput
          style={[inputStyle, styles.fieldInput]}
          value={origin}
          onChangeText={onOriginChange}
          placeholder="My location"
          placeholderTextColor={colors.textDisabled}
          returnKeyType="next"
          editable={!disabled}
          accessibilityLabel="Origin location"
          accessibilityHint="Enter your starting location"
          testID="search-origin-input"
        />
      </View>

      {/* Swap button */}
      <Pressable
        onPress={handleSwap}
        disabled={disabled}
        accessibilityRole="button"
        accessibilityLabel="Swap origin and destination"
        accessibilityHint="Exchanges the start and end locations"
        style={({ pressed }: { pressed: boolean }) => [
          styles.swapButton,
          { backgroundColor: colors.surfaceElevated },
          pressed && { backgroundColor: colors.borderMuted },
        ]}
        testID="search-swap-btn"
      >
        <Text style={[styles.swapIcon, { color: colors.accent }]}>⇅</Text>
      </Pressable>

      {/* Destination field */}
      <View style={styles.fieldWrapper}>
        <Text
          style={[
            styles.fieldIcon,
            { color: colors.textMuted, fontSize: 14 },
          ]}
          accessibilityElementsHidden
        >
          ⊕
        </Text>
        <TextInput
          style={[inputStyle, styles.fieldInput]}
          value={destination}
          onChangeText={onDestinationChange}
          placeholder="Where to?"
          placeholderTextColor={colors.textDisabled}
          returnKeyType="go"
          onSubmitEditing={handleSearch}
          editable={!disabled}
          accessibilityLabel="Destination"
          accessibilityHint="Enter your destination"
          testID="search-destination-input"
        />
      </View>

      {/* Search button */}
      <Pressable
        onPress={handleSearch}
        disabled={disabled}
        accessibilityRole="button"
        accessibilityLabel="Get directions"
        accessibilityHint="Starts navigation to the destination"
        style={({ pressed }: { pressed: boolean }) => [
          styles.searchButton,
          { backgroundColor: colors.accent },
          pressed && { backgroundColor: colors.accentMuted },
          disabled && styles.buttonDisabled,
        ]}
        testID="search-submit-btn"
      >
        <Text style={[styles.searchIcon, { color: colors.textInverse }]}>→</Text>
      </Pressable>
    </View>
  );
}

// ─── Styles ─────────────────────────────────────────────────────────────────

const styles = StyleSheet.create({
  pill: {
    flexDirection: 'row',
    alignItems: 'center',
    borderRadius: 28,
    paddingHorizontal: 12,
    paddingVertical: 8,
    gap: 6,
    // Shadow
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.15,
    shadowRadius: 8,
    elevation: 6,
  },
  pillDisabled: {
    opacity: 0.5,
  },
  fieldWrapper: {
    flex: 1,
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
  },
  fieldIcon: {
    width: 16,
    textAlign: 'center',
  },
  fieldInput: {
    paddingLeft: 0,
    paddingRight: 8,
  },
  swapButton: {
    width: 32,
    height: 32,
    borderRadius: 16,
    alignItems: 'center',
    justifyContent: 'center',
    flexShrink: 0,
  },
  swapIcon: {
    fontSize: 16,
    fontWeight: '700',
  },
  searchButton: {
    width: 36,
    height: 36,
    borderRadius: 18,
    alignItems: 'center',
    justifyContent: 'center',
    flexShrink: 0,
  },
  buttonDisabled: {
    opacity: 0.5,
  },
  searchIcon: {
    fontSize: 16,
    fontWeight: '700',
  },
});

/**
 * FloatingFloorSwitcher — horizontal scrollable row of floor pills.
 *
 * Renders a horizontally scrolling list of floor-number buttons.
 * The currently selected floor is highlighted with the accent color.
 * Used in the floating UI layer above the map to switch floors quickly.
 *
 * Usage:
 *   <FloatingFloorSwitcher
 *     floors={[{ buildingId: 1, floorNumber: 1 }, { buildingId: 1, floorNumber: 2 }]}
 *     selectedFloor={{ buildingId: 1, floorNumber: 2 }}
 *     onSelectFloor={(target) => setSelectedFloor(target)}
 *   />
 */

import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';
import { useTheme } from '../../theme';
import { FloorPlanTarget } from '../../data/mapApiClient';

export interface FloatingFloorSwitcherProps {
  /** All available floors to display as pills. */
  floors: FloorPlanTarget[];
  /** Currently selected floor. */
  selectedFloor: FloorPlanTarget;
  /** Called when the user selects a different floor. */
  onSelectFloor: (target: FloorPlanTarget) => void;
  /** Optional extra styles applied to the scroll container. */
  style?: object;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/** Returns a human-readable label for a floor, e.g. "Floor 2". */
function floorLabel(target: FloorPlanTarget): string {
  return `Floor ${target.floorNumber}`;
}

// ─── Component ────────────────────────────────────────────────────────────────

export function FloatingFloorSwitcher({
  floors,
  selectedFloor,
  onSelectFloor,
  style,
}: FloatingFloorSwitcherProps) {
  const { colors, spacing } = useTheme();

  if (!floors || floors.length === 0) {
    return null;
  }

  const isSelected = (target: FloorPlanTarget) =>
    target.buildingId === selectedFloor.buildingId &&
    target.floorNumber === selectedFloor.floorNumber;

  return (
    <View
      style={[
        styles.container,
        { backgroundColor: colors.surface },
        style,
      ]}
      accessibilityLabel="Floor switcher"
      accessibilityRole="tablist"
    >
      <ScrollView
        horizontal
        showsHorizontalScrollIndicator={false}
        contentContainerStyle={styles.scrollContent}
      >
        {floors.map((floor, index) => {
          const selected = isSelected(floor);
          return (
            <Pressable
              key={`${floor.buildingId}-${floor.floorNumber}-${index}`}
              onPress={() => onSelectFloor(floor)}
              accessibilityRole="tab"
              accessibilityState={{ selected }}
              accessibilityLabel={floorLabel(floor)}
              accessibilityHint="Switches to this floor on the map"
              style={({ pressed }: { pressed: boolean }) => [
                styles.pill,
                {
                  backgroundColor: selected
                    ? colors.chipActive
                    : colors.surfaceElevated,
                  borderColor: selected
                    ? colors.borderAccent
                    : colors.borderMuted,
                },
                pressed && {
                  backgroundColor: selected
                    ? colors.accentSubtle
                    : colors.border,
                },
              ]}
              testID={`floor-pill-${floor.floorNumber}`}
            >
              <Text
                style={[
                  styles.pillText,
                  {
                    color: selected
                      ? colors.chipTextActive
                      : colors.textSecondary,
                    fontWeight: selected ? '700' : '500',
                  },
                ]}
              >
                {floor.floorNumber}
              </Text>
            </Pressable>
          );
        })}
      </ScrollView>
    </View>
  );
}

// ─── Styles ─────────────────────────────────────────────────────────────────

const styles = StyleSheet.create({
  container: {
    borderRadius: 22,
    paddingVertical: 6,
    paddingHorizontal: 10,
    // Shadow
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 1 },
    shadowOpacity: 0.12,
    shadowRadius: 4,
    elevation: 4,
  },
  scrollContent: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
  },
  pill: {
    minWidth: 36,
    height: 32,
    borderRadius: 16,
    borderWidth: 1,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 12,
  },
  pillText: {
    fontSize: 14,
  },
});

/**
 * DirectionStepCard — single turn-by-turn instruction card.
 *
 * Displays a direction step with icon, instruction text, distance, and
 * duration.  State-based accent coloring:
 *   - default    → normal surface styling
 *   - active     → accent border highlight
 *   - accessible → success accent (for elevator/ramp segments)
 *   - stairs     → warning accent (for stairs steps)
 *   - arrived    → green highlight for the final destination step
 *
 * DirectionStep typed from mobile/domain/navGraph.ts.
 *
 * Usage:
 *   <DirectionStepCard
 *     step={step}
 *     isActive={index === currentStepIndex}
 *     onPress={() => onStepPress(index)}
 *   />
 */

import { Pressable, StyleSheet, Text, View } from 'react-native';
import { useTheme } from '../../theme';
import { DirectionStep, StepIcon } from '../../domain/navGraph';

export interface DirectionStepCardProps {
  /** The direction step to display. */
  step: DirectionStep;
  /** Highlight the card when this step is the active guidance step. */
  isActive?: boolean;
  /** Called when the user taps the card. */
  onPress?: () => void;
  /** Optional extra styles applied to the card container. */
  style?: object;
}

// ─── Icon helpers ─────────────────────────────────────────────────────────────

const STEP_ICONS: Record<string, string> = {
  'straight': '↑',
  'turn-left': '←',
  'turn-right': '→',
  'sharp-left': '↙',
  'sharp-right': '↘',
  'arrive': '🏁',
  'accessible': '♿',
  'stairs-up': '⬆',
  'stairs-down': '⬇',
  'elevator': '🛗',
  'ramp': '♿',
};

function stepIconEmoji(icon: StepIcon): string {
  return STEP_ICONS[icon] ?? '→';
}

// ─── Distance / duration formatting ────────────────────────────────────────────

/**
 * Format normalized distance as a human-readable string.
 * 1 normalized unit ≈ 50 m.
 */
function formatDistance(norm: number): string {
  const meters = Math.round(norm * 50);
  if (meters < 1) return '<1m';
  if (meters >= 1000) return `${(meters / 1000).toFixed(1)}km`;
  return `${meters}m`;
}

/** Format seconds as a human-readable duration string. */
function formatDuration(seconds: number): string {
  if (seconds < 60) return `${seconds}s`;
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  if (secs === 0) return `${mins}min`;
  return `${mins}min ${secs}s`;
}

// ─── Accent variant ───────────────────────────────────────────────────────────

type AccentVariant = 'default' | 'active' | 'accessible' | 'stairs' | 'arrived';

function accentVariant(step: DirectionStep, isActive?: boolean): AccentVariant {
  if (step.icon === 'arrive') return 'arrived';
  if (isActive) return 'active';
  if (step.icon === 'elevator' || step.icon === 'ramp') return 'accessible';
  if (step.icon === 'stairs-up' || step.icon === 'stairs-down') return 'stairs';
  return 'default';
}

// ─── Component ────────────────────────────────────────────────────────────────

export function DirectionStepCard({
  step,
  isActive = false,
  onPress,
  style,
}: DirectionStepCardProps) {
  const { colors } = useTheme();

  const variant = accentVariant(step, isActive);

  const borderColor =
    variant === 'arrived'
      ? colors.success
      : variant === 'active'
        ? colors.borderAccent
        : variant === 'accessible'
          ? colors.success
          : variant === 'stairs'
            ? colors.warning
            : colors.guidanceCardBorder;

  const iconBgColor =
    variant === 'arrived'
      ? colors.successSubtle
      : variant === 'accessible'
        ? colors.successSubtle
        : variant === 'stairs'
          ? colors.warning + '33'  // warning with alpha
          : colors.guidanceStepIcon;

  const iconColor =
    variant === 'arrived'
      ? colors.success
      : variant === 'accessible'
        ? colors.success
        : variant === 'stairs'
          ? colors.warning
          : colors.accent;

  const cardBg =
    variant === 'arrived'
      ? colors.successSubtle
      : colors.guidanceCard;

  const textColor =
    variant === 'arrived'
      ? colors.successMuted
      : variant === 'active'
        ? colors.textPrimary
        : colors.textSecondary;

  const distanceColor =
    variant === 'arrived'
      ? colors.success
      : variant === 'accessible'
        ? colors.successMuted
        : variant === 'stairs'
          ? colors.warningMuted
          : colors.accent;

  const icon = stepIconEmoji(step.icon);
  const distance = formatDistance(step.distanceM);
  const duration = formatDuration(step.durationSec);

  const CardWrapper = onPress ? Pressable : View;

  return (
    <CardWrapper
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={`${step.instruction}, ${distance}, ${duration}`}
      accessibilityHint="Tap to highlight this step on the map"
      style={({ pressed }: { pressed: boolean }) => [
        styles.card,
        {
          backgroundColor: cardBg,
          borderColor,
          borderWidth: variant === 'default' ? 1 : 1.5,
        },
        pressed && onPress && styles.cardPressed,
        style,
      ]}
      testID={`direction-step-card-${step.icon}`}
    >
      {/* Icon container */}
      <View
        style={[
          styles.iconContainer,
          { backgroundColor: iconBgColor },
        ]}
      >
        <Text style={[styles.icon, { color: iconColor }]}>{icon}</Text>
      </View>

      {/* Instruction + meta */}
      <View style={styles.content}>
        <Text
          style={[styles.instruction, { color: textColor }]}
          numberOfLines={2}
        >
          {step.instruction}
        </Text>
        <View style={styles.metaRow}>
          <Text style={[styles.metaText, { color: distanceColor }]}>
            {distance}
          </Text>
          <Text style={[styles.metaDot, { color: colors.textDisabled }]}>·</Text>
          <Text style={[styles.metaText, { color: colors.textMuted }]}>
            {duration}
          </Text>
          {step.isAccessibleSegment && (
            <>
              <Text style={[styles.metaDot, { color: colors.textDisabled }]}>·</Text>
              <Text style={[styles.metaText, { color: colors.success }]}>
                ♿ Accessible
              </Text>
            </>
          )}
        </View>
      </View>

      {/* Floor badge */}
      <View
        style={[styles.floorBadge, { backgroundColor: colors.guidanceFloorBadge }]}
      >
        <Text style={[styles.floorBadgeText, { color: colors.textInverse }]}>
          {step.floorNumber}
        </Text>
      </View>
    </CardWrapper>
  );
}

// ─── Styles ─────────────────────────────────────────────────────────────────

const styles = StyleSheet.create({
  card: {
    flexDirection: 'row',
    alignItems: 'center',
    borderRadius: 12,
    padding: 12,
    gap: 12,
    marginVertical: 3,
  },
  cardPressed: {
    opacity: 0.8,
  },
  iconContainer: {
    width: 40,
    height: 40,
    borderRadius: 10,
    alignItems: 'center',
    justifyContent: 'center',
    flexShrink: 0,
  },
  icon: {
    fontSize: 20,
  },
  content: {
    flex: 1,
    gap: 3,
  },
  instruction: {
    fontSize: 14,
    fontWeight: '600',
    lineHeight: 20,
  },
  metaRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
  },
  metaText: {
    fontSize: 12,
    fontWeight: '500',
  },
  metaDot: {
    fontSize: 12,
  },
  floorBadge: {
    width: 28,
    height: 28,
    borderRadius: 6,
    alignItems: 'center',
    justifyContent: 'center',
    flexShrink: 0,
  },
  floorBadgeText: {
    fontSize: 12,
    fontWeight: '700',
  },
});

/**
 * RouteSummaryStrip — compact horizontal route overview.
 *
 * Displays a single row with:
 *   - Total distance (e.g. "350m")
 *   - Estimated time (e.g. "4 min")
 *   - Step count (e.g. "6 steps")
 *
 * Used in the route preview bottom sheet as the header strip above
 * the step list.
 *
 * Usage:
 *   <RouteSummaryStrip
 *     totalDistanceNorm={7.2}
 *     totalDurationSec={240}
 *     stepCount={6}
 *   />
 */

import { StyleSheet, Text, View } from 'react-native';
import { useTheme } from '../../theme';

export interface RouteSummaryStripProps {
  /** Total route distance in normalized units (≈ 50 m per unit). */
  totalDistanceNorm: number;
  /** Total route duration in seconds. */
  totalDurationSec: number;
  /** Number of direction steps in the route. */
  stepCount: number;
  /** Optional extra styles applied to the container. */
  style?: object;
}

// ─── Formatting helpers ────────────────────────────────────────────────────────

/**
 * Format normalized distance as a human-readable string.
 * 1 normalized unit ≈ 50 m.
 */
function formatDistance(norm: number): string {
  const meters = Math.round(norm * 50);
  if (meters < 1) return '<1m';
  if (meters >= 1000) return `${(meters / 1000).toFixed(1)} km`;
  return `${meters} m`;
}

/** Format seconds as a localized duration string. */
function formatDuration(seconds: number): string {
  if (seconds < 60) return `${Math.round(seconds)} sec`;
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  if (secs === 0) return `${mins} min`;
  return `${mins} min ${secs} sec`;
}

// ─── Component ────────────────────────────────────────────────────────────────

export function RouteSummaryStrip({
  totalDistanceNorm,
  totalDurationSec,
  stepCount,
  style,
}: RouteSummaryStripProps) {
  const { colors, spacing } = useTheme();

  const distanceLabel = formatDistance(totalDistanceNorm);
  const durationLabel = formatDuration(totalDurationSec);
  const stepLabel = stepCount === 1 ? '1 step' : `${stepCount} steps`;

  return (
    <View
      style={[
        styles.strip,
        { backgroundColor: colors.surfaceElevated, borderColor: colors.border },
        style,
      ]}
      accessibilityLabel={`Route summary: ${distanceLabel}, ${durationLabel}, ${stepLabel}`}
      accessibilityRole="text"
    >
      {/* Distance */}
      <View style={styles.chunk}>
        <Text style={[styles.icon, { color: colors.accent }]}>↗</Text>
        <Text style={[styles.value, { color: colors.textPrimary }]}>
          {distanceLabel}
        </Text>
      </View>

      {/* Divider */}
      <View style={[styles.divider, { backgroundColor: colors.border }]} />

      {/* Duration */}
      <View style={styles.chunk}>
        <Text style={[styles.icon, { color: colors.accent }]}>⏱</Text>
        <Text style={[styles.value, { color: colors.textPrimary }]}>
          {durationLabel}
        </Text>
      </View>

      {/* Divider */}
      <View style={[styles.divider, { backgroundColor: colors.border }]} />

      {/* Step count */}
      <View style={styles.chunk}>
        <Text style={[styles.icon, { color: colors.accent }]}>⋯</Text>
        <Text style={[styles.value, { color: colors.textSecondary }]}>
          {stepLabel}
        </Text>
      </View>
    </View>
  );
}

// ─── Styles ─────────────────────────────────────────────────────────────────

const styles = StyleSheet.create({
  strip: {
    flexDirection: 'row',
    alignItems: 'center',
    borderRadius: 10,
    borderWidth: 1,
    paddingVertical: 10,
    paddingHorizontal: 16,
    gap: 12,
  },
  chunk: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 5,
  },
  icon: {
    fontSize: 13,
  },
  value: {
    fontSize: 14,
    fontWeight: '600',
  },
  divider: {
    width: 1,
    height: 16,
  },
});

/**
 * StartGuidanceButton — animated call-to-action button to begin turn-by-turn guidance.
 *
 * Renders a large pill-shaped Pressable that scales up on press.
 * Uses react-native-reanimated `withSpring` for a snappy feel.
 *
 * Usage:
 *   <StartGuidanceButton
 *     onPress={() => startGuidance(route)}
 *     disabled={!route}
 *   />
 */

import { StyleSheet, Text, View } from 'react-native';
import { Pressable } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';

import { useTheme } from '../../theme';

export interface StartGuidanceButtonProps {
  /** Called when the user presses the button. */
  onPress: () => void;
  /** Prevent interaction when true. */
  disabled?: boolean;
  /** Label shown on the button. Defaults to "Start Guidance". */
  label?: string;
  /** Optional extra styles applied to the button container. */
  style?: object;
}

// Spring config for snappy scale animation
const SPRING_CONFIG = {
  damping: 15,
  stiffness: 400,
  mass: 0.8,
};

const PRESSED_SCALE = 0.93;

export function StartGuidanceButton({
  onPress,
  disabled = false,
  label = 'Start Guidance',
  style,
}: StartGuidanceButtonProps) {
  const { colors } = useTheme();
  const scale = useSharedValue(1);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  const handlePressIn = () => {
    scale.value = withSpring(PRESSED_SCALE, SPRING_CONFIG);
  };

  const handlePressOut = () => {
    scale.value = withSpring(1, SPRING_CONFIG);
  };

  return (
    <Animated.View style={[styles.wrapper, animatedStyle, style]}>
      <Pressable
        onPress={disabled ? undefined : onPress}
        onPressIn={disabled ? undefined : handlePressIn}
        onPressOut={disabled ? undefined : handlePressOut}
        disabled={disabled}
        accessibilityRole="button"
        accessibilityLabel={label}
        accessibilityHint="Begins turn-by-turn navigation to the selected destination"
        accessibilityState={{ disabled }}
        style={({ pressed }: { pressed: boolean }) => [
          styles.button,
          { backgroundColor: colors.accent },
          pressed && !disabled && { backgroundColor: colors.accentMuted },
          disabled && styles.buttonDisabled,
        ]}
        testID="start-guidance-btn"
      >
        {/* Navigation arrow icon */}
        <View style={[styles.iconWrapper, { backgroundColor: colors.textInverse + '1f' }]}>
          <Text style={[styles.icon, { color: colors.accent }]}>➤</Text>
        </View>

        {/* Label */}
        <Text
          style={[
            styles.label,
            { color: colors.textInverse },
            disabled && { color: colors.textDisabled },
          ]}
        >
          {label}
        </Text>
      </Pressable>
    </Animated.View>
  );
}

// ─── Styles ─────────────────────────────────────────────────────────────────

const styles = StyleSheet.create({
  wrapper: {
    alignSelf: 'stretch',
  },
  button: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 28,
    paddingVertical: 16,
    paddingHorizontal: 24,
    gap: 10,
    // Shadow
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.25,
    shadowRadius: 10,
    elevation: 8,
  },
  buttonDisabled: {
    backgroundColor: '#334155',
    opacity: 0.6,
    shadowOpacity: 0,
    elevation: 0,
  },
  iconWrapper: {
    width: 32,
    height: 32,
    borderRadius: 16,
    alignItems: 'center',
    justifyContent: 'center',
  },
  icon: {
    fontSize: 14,
    fontWeight: '700',
  },
  label: {
    fontSize: 17,
    fontWeight: '700',
    letterSpacing: 0.2,
  },
});

